$(document).ready(function() {
	var SITE_URL = document.location.origin;
	jQuery(".searchForm").on("click", function (event) {
		if($('#search-details').val() != ""){
			var data = $('#searchForm').serialize();
			var filterUrl = SITE_URL + '/' + 'products/getFilterParam';	 
			$.ajax({
				url	:	filterUrl,
				type:	'POST',
				data:	 data,
				success : function(response) { 
					var redirectUrl = 'Products/';
					setTimeout(function(){ location.href = SITE_URL + '/'+redirectUrl+response; }, 100);
				}
			});
		}else{
			$(".searchbar").css("border", "1px solid red");
		}
	});
	
	jQuery("#searchForm").on("submit", function (event) {
		if($('#search-details').val() != ""){
			var data = $('#searchForm').serialize();
			var filterUrl = SITE_URL + '/' + 'products/getFilterParam';	 
			$.ajax({
				url	:	filterUrl,
				type:	'POST',
				data:	 data,
				success : function(response) { 
					var redirectUrl = 'Products/';
					setTimeout(function(){ location.href = SITE_URL + '/'+redirectUrl+response; }, 100);
				}
			});
		}else{
			$(".searchbar").css("border", "1px solid red");
		}
	});
	
	var curPgurl = window.location.href;	
	jQuery(".filtercheckbox").on("click", function (event) {
		var curVal = $(this).val();
		var typo = $(this).attr('filterTypo');
		
			if(jQuery(this).is(':checked')){
				var data = $('#CustomerRugsForm').serialize();
			}
			else{
				var data = $('#CustomerRugsForm').serialize();
			}
			
			var filterUrl = SITE_URL + '/products/getFilterParam';	 
			$.ajax({
				url	:	filterUrl,
				type:	'POST',
				data:	 data,
				success : function(response) { 
				//alert(response);
					if(response == ""){
						response = "shopping";
					}
					
					var redirectUrl = 'Products/';
					setTimeout(function(){ location.href = SITE_URL + '/'+redirectUrl+response; }, 100);
			    }
			});
	});
});